// ============================================================
// CONFIG: Paste your API keys here
// ============================================================
const GROQ_API_KEY = 'YOUR_GROQ_API_KEY_HERE';
const ANTI_FRAUD_API_KEY = 'YOUR_ANTI_FRAUD_API_KEY_HERE';
// ============================================================

const webhookData = $json;

return [{
  json: {
    config: {
      groq_api_key: GROQ_API_KEY,
      anti_fraud_api_key: ANTI_FRAUD_API_KEY
    },
    body: webhookData.body
  }
}];

const userText = $json.body.text || '';
const hasImage = !!$json.body.image_base64;

const systemPrompt = `You are an anti-fraud analysis router. Analyze the user's message and extract:
1. Any URLs (http://, https://, or bare domains like example.com)
2. Any phone numbers (any format: +886..., 09..., 02-xxxx-xxxx, etc.)
3. Whether an image was provided for content analysis

Return ONLY valid JSON:
{
  "urls": ["https://example.com"],
  "phones": [{"country": "TW", "number": "+886289667000"}],
  "need_content_check": false,
  "summary": "brief description of what was found"
}

Rules:
- For Taiwan numbers without country code (e.g. 0289667000, 09xx), remove leading 0, prepend +886, set country to "TW"
- For URLs without protocol, prepend https://
- Set need_content_check to true ONLY if has_image is true
- If nothing is found, return empty arrays
- ONLY return the JSON object, no markdown, no explanation`;

const userMessage = userText + '\n\n[has_image: ' + hasImage + ']';

return [{
  json: {
    groq_body: {
      model: 'llama-3.3-70b-versatile',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userMessage }
      ],
      temperature: 0,
      max_tokens: 512,
      response_format: { type: 'json_object' }
    },
    original_text: userText,
    image_base64: $json.body.image_base64 || null
  }
}];

const groqResp = $json;
const prevData = $('Prepare Groq Request').first().json;

let parsed;
try {
  const content = groqResp.choices[0].message.content;
  parsed = JSON.parse(content);
} catch (e) {
  parsed = { urls: [], phones: [], need_content_check: false, summary: 'LLM parse error: ' + e.message };
}

return [{
  json: {
    urls: parsed.urls || [],
    phones: parsed.phones || [],
    need_content_check: !!parsed.need_content_check,
    summary: parsed.summary || '',
    original_text: prevData.original_text,
    image_base64: prevData.image_base64
  }
}];

const data = $json;
const API_KEY = $('Config').first().json.config.anti_fraud_api_key;
const BASE = 'https://hljaj2f6gf.execute-api.ap-northeast-1.amazonaws.com/prod';

const results = { url_results: [], number_results: [], content_result: null };
const self = this;

// --- URL Check ---
for (let i = 0; i < data.urls.length; i++) {
  const url = data.urls[i];
  if (i > 0) await new Promise(r => setTimeout(r, 1100));
  try {
    const d = await self.helpers.httpRequest({
      method: 'POST',
      url: `${BASE}/url-check`,
      headers: { 'x-api-key': API_KEY, 'Content-Type': 'application/json' },
      body: { url },
      json: true
    });
    results.url_results.push({
      url, http_status: 200,
      score: d.score ?? null,
      domain: d.domain ?? url,
      blacklisted: d.blacklisted ?? null
    });
  } catch (e) {
    results.url_results.push({ url, http_status: e.statusCode || 0, error: e.message });
  }
}

// --- Number Check ---
for (let i = 0; i < data.phones.length; i++) {
  const phone = data.phones[i];
  if (i > 0) await new Promise(r => setTimeout(r, 1100));
  try {
    const d = await self.helpers.httpRequest({
      method: 'GET',
      url: `${BASE}/number-check/${phone.country}/${encodeURIComponent(phone.number)}`,
      headers: { 'x-api-key': API_KEY },
      json: true
    });
    results.number_results.push({
      number: phone.number, country: phone.country, http_status: 200,
      name: d.data?.name ?? null,
      business_categories: d.data?.business_categories ?? [],
      spam_category: d.data?.spam_category ?? null
    });
  } catch (e) {
    results.number_results.push({ number: phone.number, country: phone.country, http_status: e.statusCode || 0, error: e.message });
  }
}

// --- Content Check ---
if (data.need_content_check && data.image_base64) {
  try {
    const uploadBody = await self.helpers.httpRequest({
      method: 'POST',
      url: `${BASE}/content-check`,
      headers: { 'x-api-key': API_KEY, 'Content-Type': 'application/json', 'Accept-Language': 'zh-TW' },
      body: { region: 'TW', image: data.image_base64 },
      json: true
    });
    const jobId = uploadBody.job_id;
    if (jobId) {
      for (let attempt = 0; attempt < 20; attempt++) {
        await new Promise(r => setTimeout(r, 3000));
        try {
          const p = await self.helpers.httpRequest({
            method: 'GET',
            url: `${BASE}/content-check/${jobId}`,
            headers: { 'x-api-key': API_KEY, 'Accept-Language': 'zh-TW' },
            json: true
          });
          if (p.status === 3) {
            results.content_result = {
              job_id: jobId, category: p.category, title: p.title,
              content: p.content, urls: p.urls, numbers: p.numbers,
              kindly_reminder: p.kindly_reminder
            };
            break;
          }
          if (p.status === 2) {
            results.content_result = { job_id: jobId, category: 'FAILED', title: 'Processing failed' };
            break;
          }
        } catch (pollErr) { /* keep polling */ }
      }
    }
  } catch (e) {
    results.content_result = { error: e.message };
  }
}

// --- Build display text ---
const lines = [];
for (const u of results.url_results) {
  if (u.score != null) {
    const risk = u.score >= 80 ? '安全' : u.score >= 50 ? '中等風險' : '高風險';
    lines.push(`URL ${u.domain}: 信任分數 ${u.score}/100 (${risk})${u.blacklisted ? ' [已列入黑名單]' : ''}`);
  } else {
    lines.push(`URL ${u.url}: 查詢失敗 (HTTP ${u.http_status})`);
  }
}
for (const n of results.number_results) {
  if (n.name) {
    lines.push(`Phone ${n.number}: ${n.name} (${n.business_categories.join(', ')})${n.spam_category ? ' [SPAM: ' + n.spam_category + ']' : ''}`);
  } else if (n.spam_category) {
    lines.push(`Phone ${n.number}: ${n.spam_category}`);
  } else {
    lines.push(`Phone ${n.number}: 無相關紀錄`);
  }
}
if (results.content_result) {
  const c = results.content_result;
  lines.push(`Screenshot: ${c.category} - ${c.title}`);
  if (c.content) c.content.forEach(l => lines.push(`  ${l}`));
}
if (lines.length === 0) {
  lines.push('未偵測到網址、電話號碼或圖片。');
}

return [{
  json: {
    summary: data.summary,
    display_text: lines.join('\n'),
    url_results: results.url_results,
    number_results: results.number_results,
    content_result: results.content_result,
    original_text: data.original_text
  }
}];
